-- Lane A figures for None: generated by build_load_sql.py, do not hand-edit.
-- 6 figures across 3 families, from scripts/lane-a-pilot/specs.json.
-- Entries are resolved by natural key, so this file is portable between environments.

begin;

-- 1. The renderer families this batch INTRODUCES (DECISION-0115: a row, not a CHECK).
-- Reused without introducing: mb_distribution
insert into app.figure_families (family_key, title, summary, renderer_note)
values ('kinematic_panels', 'Stacked kinematic panels', 'Three panels sharing one time axis -- position, velocity and acceleration of a single motion -- with drawn tangents and shaded areas, because every labelled part of the entry is a relationship BETWEEN the panels.', 'scripts/lane-a-pilot/render.py; the app''s figure renderer')
on conflict (family_key) do nothing;
insert into app.figure_families (family_key, title, summary, renderer_note)
values ('xy_series', 'General x-y series', 'Curves from explicit points, scatter, an optional shaded area under one curve and a zero line. Carries the PV diagram, electric potential around a circuit loop and the residual plot: different sciences, one geometry.', 'scripts/lane-a-pilot/render.py; the app''s figure renderer')
on conflict (family_key) do nothing;

-- 2. The figures.
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('chem-mb-energy', 'ap_chemistry', 'mb_distribution', 'Maxwell–Boltzmann energy distribution', 'Maxwell-Boltzmann energy distribution', 'Raising the temperature increases the fraction of particles beyond Ea', 'Raising the temperature increases the fraction of particles beyond Ea', 'Two distribution curves of relative number of particles against particle energy. The higher-temperature curve is lower at its peak, broader and shifted right, so a larger shaded area lies beyond the vertical activation-energy marker. Illustrative data.', 'particle energy', 'relative number of particles', 'Area beyond Ea estimates the fraction of collisions with sufficient energy.', true, null, '["Horizontal axis", "Vertical axis", "Distribution curve", "Activation energy marker", "Area beyond the marker", "Curves at different temperatures"]'::jsonb, '{"x_max": 8.0, "series": [{"label": "Lower temperature", "theta": 0.78, "style": "solid"}, {"label": "Higher temperature", "theta": 1.48, "style": "dashed"}], "markers": [{"x": 2.75, "label": "Ea", "caption": "activation energy"}]}'::jsonb, '{:.2f}', null, 'published', 'cramapple-authored; batch=phys-work,phys2-zero,phys2-ohmic,chem-mb-catalysis,physcmech-xva,chem-mb-energy-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('chem-mb-catalysis', 'ap_chemistry', 'mb_distribution', 'Maxwell–Boltzmann distribution: effect of a catalyst', 'Catalyst lowers Ea', 'A catalyst lowers Ea, so more particles clear the barrier at the same temperature', 'A catalyst lowers Ea, so more particles clear the barrier at the same temperature', 'One distribution curve of number of particles against kinetic energy at a fixed temperature, with two vertical activation-energy markers. The catalysed barrier sits to the left of the uncatalysed one, so the shaded area beyond it is larger. Illustrative data.', 'kinetic energy', 'number of particles', 'Same temperature, same curve: only the barrier moves.', true, null, '["Distribution curve at a fixed temperature", "Uncatalysed activation energy (Ea)", "Catalysed activation energy (Ea′)", "Area beyond the catalysed barrier", "Same temperature, same curve"]'::jsonb, '{"x_max": 8.0, "series": [{"label": "Particles at this temperature", "theta": 1.1, "style": "solid"}], "markers": [{"x": 1.9, "label": "Ea''", "caption": "catalysed"}, {"x": 3.4, "label": "Ea", "caption": "uncatalysed"}]}'::jsonb, '{:.2f}', null, 'published', 'cramapple-authored; batch=phys-work,phys2-zero,phys2-ohmic,chem-mb-catalysis,physcmech-xva,chem-mb-energy-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('physcmech-xva-graphs', 'ap_physics_c_mechanics', 'kinematic_panels', 'Reading x(t), v(t) and a(t) together', 'x(t), v(t), a(t)', 'Slope of one graph is the value of the next; area under one is the change in the one above', 'One motion at constant acceleration, shown three ways: slopes read downward, areas read upward.', 'Three stacked graphs of the same motion against a shared time axis. The top panel is position against time, a curve whose tangent is drawn at one instant: the slope of that tangent is the instantaneous velocity. The middle panel is velocity against time, a straight line whose own slope is the constant acceleration, with the area under it between two times shaded, because that area is the displacement over the interval. The bottom panel is acceleration against time, a horizontal line, whose area over an interval is the change in velocity. Illustrative data.', 'time t', '', 'Slopes read downward (x to v to a); areas read upward (a to v to x).', true, null, '["Slope of tangent on x–t graph", "Slope of tangent on v–t graph", "Area under v–t curve", "Area under a–t curve"]'::jsonb, '{"x0": 0.0, "v0": 2.0, "a": 1.5, "t_max": 6.0, "x_label_panel": "x(t)  position", "v_label_panel": "v(t)  velocity", "a_label_panel": "a(t)  acceleration", "annotations": [{"panel": "x", "t": 3.0, "y": 12.75, "label": "slope = v(3)", "tangent": true, "slope": 6.5}, {"panel": "v", "t": 3.0, "y": 6.5, "label": "slope = a", "tangent": true, "slope": 1.5}], "shades": [{"panel": "v", "t0": 2.0, "t1": 4.0, "label": "area = Δx"}, {"panel": "a", "t0": 2.0, "t1": 4.0, "label": "area = Δv"}]}'::jsonb, null, null, 'published', 'cramapple-authored; batch=phys-work,phys2-zero,phys2-ohmic,chem-mb-catalysis,physcmech-xva,chem-mb-energy-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('phys-work-force-displacement', 'ap_physics_1', 'xy_series', 'Work as the area under a force-displacement graph', 'Work is the area', 'Only the component of force along the motion counts', 'The component of the force along the motion, against displacement. The force is constant for the first 2 m, then falls steadily to zero at 6 m; the shaded area is the work it does.', 'A graph of the component of a force along the direction of motion, against displacement. The force holds steady at 8 newtons from 0 to 2 metres, then falls in a straight line to zero at 6 metres. The whole region between that line and the horizontal axis is shaded, because the area under the graph is the work the force does: 16 joules from the flat part and 16 more from the triangle, 32 joules in total. Reading a value off the curve gives a force, not a work; only the area is the work. Illustrative data.', 'displacement along the motion (m)', 'force component along the motion (N)', 'Area = 32 J: the rectangle is 16 J and the triangle is 16 J.', true, null, '["Force component along the motion", "Displacement along the motion", "Shaded area is the work done"]'::jsonb, '{"x_range": [-0.3, 6.6], "y_range": [-0.9, 9.6], "y_ticks": [0, 2, 4, 6, 8], "work_area_check": 32.0, "series": [{"label": "force along the motion", "style": "solid", "fill_under": true, "points": [[0.0, 8.0], [2.0, 8.0], [6.0, 0.0]]}]}'::jsonb, '{:.0f}', null, 'published', 'cramapple-authored; batch=phys-work,phys2-zero,phys2-ohmic,chem-mb-catalysis,physcmech-xva,chem-mb-energy-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('phys2-zero-pressure-temperature', 'ap_physics_2', 'xy_series', 'Finding the zero-pressure temperature by extrapolation', 'Extrapolate to P = 0', 'The line is extended well past the measurements to reach zero pressure', 'Pressure of a fixed amount of gas held at constant volume, measured between 0 °C and 100 °C, with the straight line extended backwards until the pressure reaches zero.', 'A graph of the pressure of a fixed sample of gas at constant volume against its temperature in degrees Celsius. Five measured points from 0 to 100 degrees lie on a rising straight line. That line is continued as a dashed extension far to the left, beyond any measurement, until it crosses zero pressure at about minus 273 degrees Celsius, which is the zero-pressure temperature. The point is reached by extending the line, not by measuring there: no gas stays a gas that cold. Illustrative data.', 'temperature (°C)', 'pressure (kPa)', 'No measurement is taken near −273 °C; the temperature is read off the extended line.', true, null, '["Measured pressure at each temperature", "Extrapolation beyond the measurements", "Zero-pressure temperature"]'::jsonb, '{"x_range": [-300.0, 130.0], "y_range": [-14.0, 152.0], "y_ticks": [0, 50, 100, 150], "x_ticks": [[-273.15, "−273"], [-150.0, "−150"], [0.0, "0"], [100.0, "100"]], "zero_pressure_check": -273.15, "series": [{"label": "extended line", "style": "dashed", "points": [[-273.15, 0.0], [0.0, 100.0]], "marks": [{"x": -273.15, "y": 0.0, "label": "P = 0 at −273 °C", "place": "above"}]}, {"label": "measured", "style": "solid", "points": [[0.0, 100.0], [25.0, 109.1524803221673], [50.0, 118.30496064433463], [75.0, 127.4574409665019], [100.0, 136.60992128866926]]}], "hlines": [{"y": 0.0, "label": "zero pressure"}]}'::jsonb, '{:.0f}', null, 'published', 'cramapple-authored; batch=phys-work,phys2-zero,phys2-ohmic,chem-mb-catalysis,physcmech-xva,chem-mb-energy-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('phys2-ohmic-iv', 'ap_physics_2', 'xy_series', 'Current against potential difference: ohmic and non-ohmic', 'Ohmic is straight', 'A straight line through the origin is what makes an element ohmic', 'Current against potential difference for two elements. The ohmic one is a straight line through the origin of slope 0.040 A/V, so its resistance is 25 Ω; the other bends, so no single resistance describes it.', 'A graph of current against potential difference for two circuit elements, both starting at the origin. The ohmic element gives a straight line: doubling the potential difference doubles the current, so the ratio is fixed and the resistance is constant at 25 ohms. The second element''s line rises steeply at first and then flattens, so equal steps in potential difference add less and less current; its ratio of potential difference to current keeps climbing and no single resistance describes it. The resistance of the ohmic element is one divided by the slope, not the slope itself. Illustrative data.', 'potential difference ΔV (V)', 'current I (A)', 'Resistance is 1/slope here: the slope is 0.040 A/V, so R = 25 Ω.', true, null, '["Ohmic element: a straight line through the origin", "Resistance is one over the slope", "Non-ohmic element: the line bends"]'::jsonb, '{"x_range": [-0.35, 5.6], "y_range": [-0.035, 0.3], "y_ticks": [0.0, 0.05, 0.1, 0.15, 0.2, 0.25], "ohmic_check": 25.0, "series": [{"label": "ohmic element", "style": "solid", "points": [[0.0, 0.0], [1.25, 0.05], [2.5, 0.1], [3.75, 0.15], [5.0, 0.2]], "marks": [{"x": 5.0, "y": 0.2, "label": "slope = 1/R", "place": "above"}]}, {"label": "non-ohmic element", "style": "dashed", "points": [[0.0, 0.0], [0.5, 0.065309], [1.0, 0.09899], [1.75, 0.138489], [2.5, 0.171536], [3.25, 0.20078], [4.0, 0.227419], [4.5, 0.244073], [5.0, 0.26]]}]}'::jsonb, '{:.2f}', null, 'published', 'cramapple-authored; batch=phys-work,phys2-zero,phys2-ohmic,chem-mb-catalysis,physcmech-xva,chem-mb-energy-figures-2026-10-11', now())
on conflict (figure_id) do nothing;

-- 3. Where each figure is shown, resolved by natural key (protocol §6).
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'chem-mb-energy', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_chemistry' and e.kind = 'diagram'
   and e.title = 'Maxwell-Boltzmann energy distribution' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;
