-- 4. Guards: no dead figure, and every entry this batch covers got its figures.
do $$
declare v_dead text; v_n int;
begin
  select string_agg(f.figure_id, ', ') into v_dead
    from app.figures f left join app.figure_uses u on u.figure_id = f.figure_id
   where f.figure_id in ('chem-mb-energy', 'chem-mb-catalysis', 'physcmech-xva-graphs', 'phys-work-force-displacement', 'phys2-zero-pressure-temperature', 'phys2-ohmic-iv') and u.figure_id is null;
  if v_dead is not null then
    raise exception 'figures with no use, refusing to ship dead rows: %', v_dead;
  end if;
  select count(*) into v_n from app.figures where figure_id in ('chem-mb-energy', 'chem-mb-catalysis', 'physcmech-xva-graphs', 'phys-work-force-displacement', 'phys2-zero-pressure-temperature', 'phys2-ohmic-iv');
  if v_n <> 6 then
    raise exception 'expected 6 figures, found %', v_n;
  end if;
end $$;

commit;
